sources.scripts/daisy-efficiency-v1/policy.ts:
import type {JevRequest} from '../../src/lib/types';
export type Variant='baseline'|'costs';
export function request(original:JevRequest,variant:Variant){
 const r=structuredClone(original);
 if(variant==='costs'){
  r.questions.routine.instructions=String(r.questions.routine.instructions)+' Among matching, unrejected lifts that preserve protectedBottomSlots, choose the smallest turnCount. A one-turn lift is preferred to a three-turn lift when both protect those slots. Do not protect unsolved bottom slots unnecessarily. Landing occupancy is checked separately after this decision. If no lift remains, choose a matching staging routine.';
  for(const [id,text] of Object.entries(r.questions.routine.criteria)){
   if(id==='reconsider')continue;
   const routine=JSON.parse(text);
   r.questions.routine.criteria[id]=JSON.stringify({...routine,turnCount:routine.sequence.split(/\s+/).length});
  }
 }
 return r;
}

sources.scripts/daisy-efficiency-v1/screen.ts:
import {readFileSync,writeFileSync} from 'node:fs';
import {request,type Variant} from './policy';
import {solved,apply,pieces} from '../../src/lib/cube';
import {createRun} from '../../src/server/runner';
import {evaluate,budget} from '../../src/server/jev';
import {db,saveRun,getRun} from '../../src/server/store';
const dir='experiments/daisy-efficiency-v1',split='daisy-efficiency-v1';
const phase=process.argv[2]??'development';if(!['development','validation'].includes(phase))throw Error('Bad phase');
const variants:Variant[]=phase==='development'?['baseline','costs']:[process.argv[3] as Variant];
if(variants.some(v=>!['baseline','costs'].includes(v)))throw Error('Bad variant');
writeFileSync(`${dir}/${phase}-started.json`,JSON.stringify({phase,variants,at:new Date().toISOString(),limits:{calls:80,dollars:.01,concurrency:2},budget:budget(),sources:Object.fromEntries(['scripts/daisy-efficiency-v1/policy.ts','scripts/daisy-efficiency-v1/screen.ts','experiments/daisy-efficiency-v1/fixtures.json','src/lib/cube.ts'].map(p=>[p,readFileSync(p,'utf8')]))},null,2),{flag:'wx'});
const fixtures=JSON.parse(readFileSync(dir+'/fixtures.json','utf8')).filter((f:any)=>f.phase===phase);
const usage=()=>db.query("SELECT COUNT(*) requests,COALESCE(SUM(amount),0) cost FROM ledger l JOIN runs r ON r.id=l.run_id WHERE json_extract(r.json,'$.split')=?").get(split) as {requests:number;cost:number};
const rows:any[]=[],jobs=variants.flatMap(variant=>fixtures.map((f:any)=>({variant,f})));let cursor=0;
const persist=()=>writeFileSync(`${dir}/${phase}-results.json`,JSON.stringify({phase,rows,usage:usage()},null,2));
async function job({variant,f}:typeof jobs[number]){
 const run=await createRun('','skills',split),row:any={id:f.id,variant,acceptable:f.acceptable,runId:run.id,status:'running'};rows.push(row);persist();
 try{
 for(let retry=0;retry<3;retry++){
  const u=usage();if(u.requests>=80||u.cost+.002688>.01||budget().reservedAndSpent+.002688>9)throw Error('Budget cap');
  try{row.exchange=await evaluate(run.id,request(f.request,variant),AbortSignal.timeout(30000),{maxAttempts:1});break;}
  catch(e){if(retry===2||!/(HTTP (429|5\d\d)|network)/i.test(String(e)))throw e;row.transportErrors??=[];row.transportErrors.push(String(e));await new Promise(r=>setTimeout(r,1000*2**retry));}
 }
 row.choice=row.exchange.response.answers.routine.choice;row.passed=f.acceptable.includes(row.choice);row.status='complete';
 }catch(e){row.status='error';row.error=String(e);row.passed=false;}
 saveRun({...getRun(run.id),status:'stopped',reason:'Isolated alignment evaluation'});persist();
}
await Promise.all(Array.from({length:2},async()=>{while(cursor<jobs.length)await job(jobs[cursor++]);}));
console.log({usage:usage(),scores:variants.map(v=>({variant:v,n:rows.filter(r=>r.variant===v).length,passed:rows.filter(r=>r.variant===v&&r.passed).length,tokens:rows.filter(r=>r.variant===v).reduce((n,r)=>n+(r.exchange?.response.usage.input_tokens??0),0)}))});

